class Solution {
public:
    int minSetSize(vector<int>& arr) {
        int n = arr.size();
        int target = n / 2;
        unordered_map<int,int> freq;
        for (int x : arr) freq[x]++;
        vector<int> buckets(n + 1, 0);
        for (auto& p : freq) buckets[p.second]++;
        int removed = 0, ans = 0;
        for (int f = n; f >= 1 && removed < target; f--) {
            while (buckets[f] > 0 && removed < target) {
                removed += f;
                ans++;
                buckets[f]--;
            }
        }
        return ans;
    }
};
